/*

Original code by AKHC: 
https://www.shadertoy.com/view/lct3DN

*/

// These are necessary definitions that let you graphics card know how to render the shader
#ifdef GL_ES
precision highp float;
#endif

// These are our passed in information from the sketch.js
uniform vec2 iResolution;
uniform vec2 iMouse;
uniform float iTime;

varying vec2 vTexCoord;

#define SEED 0.12345679
#define DIE_TIME 1.2
#define SIZE 0.2134
#define PI 3.14159265359

float smin( float a, float b, float k )
{
    k *= 4.0;
    float h = max( k-abs(a-b), 0.0 )/k;
    return min( a, b ) - h*h*k*(1.0/4.0);
}

float sdSphere( vec3 p, float s )
{
  return length(p)-s;
}

vec3 palette0( in float t)
{
    vec3 a = vec3(0.756, 0.054, 0.590);
    vec3 b = vec3(0.787, 0.227, 0.048);
    vec3 c = vec3(1.195, 0.263, 0.702);
    vec3 d = vec3(2.939, 0.116, 3.415);

    return a + b*cos( 6.28318*(c*t+d) );
}

float rand (vec2 p) {
    return fract(sin(dot(p.xy,
                         vec2(6.8245,7.1248)))*
        9.1283);
}

struct Part
{
    float spawnedTime;
    vec2 anchor;
    vec2 velocity;
};

Part particles[60];

float processParticle(Part pData, vec2 uv, float creationTime)
{
    float particleTime = max(0., iTime - creationTime); //is 0 until reaching index time

    float size = SIZE * max(0., DIE_TIME - particleTime);

    //velocity basically is 0 and starts increasing constantly after a certain time
    vec2 velocityOffset = pData.velocity * particleTime; 

    vec2 point = pData.anchor + velocityOffset;

    float dist = distance(uv, point);
    float hit = smoothstep(size, 0., dist);

    return hit;
}

vec3 currentColorTEST() {
  float c = iTime * 0.2;
  float r = sin(c * PI) / 2. + .5;
  float g = sin((c + .6) * PI) / 2. + .5;
  float b = sin((c + 1.2) * PI) / 2. + .5;
  return vec3(r, g, b);
}


//distance to scene function
float map(vec3 p)
{

    vec3 q = p; //input point copy

    float sphere = sdSphere(p, 0.6);

    return sphere;
}


//https://iquilezles.org/articles/palettes/
vec3 palette1( float t ) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.263, 0.416, 0.557);

		//vec3 a = vec3(0.198, 0.438, 0.698);
    //vec3 b = vec3(-0.262, 0.208, 0.238);
    //vec3 c = vec3(2.238, 2.168, 1.000);
    //vec3 d = vec3(-0.052, 0.333, 0.667);

    return a + b * cos( 6.28318*(c * t + d) );
}

void main() {
    // copy the vTexCoord
    // vTexCoord is a value that goes from 0.0 - 1.0 depending on the pixels location
    // we can use it to access every pixel on the screen

    vec2 coord = vTexCoord;

    float u = coord.x * 2.0 - 1.0;
    float v = coord.y * 2.0 - 1.0;
    const float scale = 1.0;

    // Make sure pixels are square
    u = u * scale * iResolution.x / iResolution.y;
    v = v * scale;

    vec2 uv = vec2(u, v);
    //vec2 uv0 = vec2(u, v);

    vec3 col = vec3(0.0);

		vec2 mousePos = vec2(0,-0.3);

    //process particles
    for (int i = 0; i < 50; i++)
    {
        float seed = SEED + floor(float(i) / 50. + iTime);
        vec2 newVelocity = vec2(mix(-.5, .5, rand(vec2(seed, float(i)))), mix(-.05, 1., rand(vec2(float(i), seed) / 3.)));
        float creationTime = iTime - fract(float(i) / 50. + iTime);


        particles[i].spawnedTime = iTime;
        particles[i].anchor += mousePos;
        particles[i].velocity += newVelocity;

        col += processParticle(particles[i], uv, creationTime) * palette1(iTime);
    }


    //col += vec3(t * .2);
    //col = smoothstep(.3, .9, col-.9); //gets rid of soft edges
		col = smoothstep(-1., 1.0, (col-0.5)/(col)); //gets rid of soft edges



  // gl_FragColor is a built in shader variable, and your .frag file must contain it
  // We are setting the vec3 color into a new vec4, with a transparency of 1 (no opacity)
	gl_FragColor = vec4(col, 1.0);
}

// === Tab: shader.vert ===
// These are necessary definitions that let you graphics card know how to render the shader
#ifdef GL_ES
precision highp float;
#endif

// our vertex data
attribute vec3 aPosition;

attribute vec2 aTexCoord;

varying vec2 vTexCoord;

void main() {

  vTexCoord = aTexCoord;

  // copy the position data into a vec4, using 1.0 as the w component
  vec4 positionVec4 = vec4(aPosition, 1.0);

  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  // send the vertex information on to the fragment shader
  gl_Position = positionVec4;
}

